-- SisterMart 退款政策 — upsert article_i18n for code=refund
INSERT INTO articles (code, status, show_in_footer, sort_order, created_at, updated_at)
SELECT 'refund', 1, 1, 60, NOW(), NOW() FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM articles WHERE code='refund');
UPDATE articles SET status=1, show_in_footer=1, sort_order=60, updated_at=NOW() WHERE code='refund';

INSERT INTO article_i18n (article_id, locale, title, body)
SELECT a.id, 'zh-HK', '退款政策', '<p><strong>生效日期：</strong>2026 年 11 月 7 日<br>\n<strong>最後更新日期：</strong>2026 年 11 月 7 日</p>\n<p>本《退款政策》說明 SisterMart（姐妹商店）何時及如何退款，並與《退貨政策》《運送政策》《用戶協議》一併適用。退款並非自動權利：須符合本政策及《退貨政策》，並經我們審核／驗貨確認。為保障店家合法權益與防範濫用，我們保留核實交易、調整退款構成、分期或延後處理，以及在合理情況下拒絕或僅部分退款之操作空間（法律強制規定除外）。</p>\n\n<h2>1. 可退款情形</h2>\n<ul>\n<li>按《退貨政策》完成退貨，且收貨檢驗<strong>合格</strong>後</li>\n<li>付款成功後，因我們原因長期未能出貨，且你選擇取消，經我們確認可取消之訂單</li>\n<li>經核實之重複扣款、系統計價錯誤、明顯多收運費或其他我方責任之金額錯誤</li>\n<li>錯發／漏發且雙方同意以退款代替補發或換貨</li>\n<li>其他我們書面同意退款之情形</li>\n</ul>\n\n<h2>2. 不退款或僅部分退款之情形</h2>\n<ul>\n<li>不符合《退貨政策》或驗貨不合格</li>\n<li>已使用之優惠權益、不可撤回之第三方費用、或商品貶值／缺件部分</li>\n<li>因顧客提供錯誤地址、拒收、不取件導致之額外物流成本（可自退款中扣除）</li>\n<li>贈品、包裝耗材、發票手續等已發生且無法退回之成本（按個案說明）</li>\n<li>涉嫌欺詐、調包、惡意拒付或濫用售後</li>\n</ul>\n\n<h2>3. 退款構成與計算</h2>\n<ol>\n<li><strong>商品款：</strong>原則按該件實付金額計算（已扣除該件分攤之優惠後）。</li>\n<li><strong>訂單優惠／滿減／券：</strong>退款後若剩餘商品不再滿足活動門檻，我們有權追回相應優惠差額（自退款中扣減或要求補差）。</li>\n<li><strong>積分：</strong>下單抵扣之積分，可按規則返還；因本筆訂單已發放之積分，我們有權扣回。積分商城兌換訂單之退款規則可另行限制。</li>\n<li><strong>運費：</strong>\n  <ul>\n    <li>質量問題／錯發：原訂單運費與經同意之寄回運費，可按合理範圍退還或報銷</li>\n    <li>非質量問題：原訂單運費通常不退；寄回與補發運費由顧客承擔</li>\n    <li>部分退貨後剩餘商品未達免運門檻：可自退款中補收應付運費</li>\n  </ul>\n</li>\n<li><strong>手續／檢測／補貨費：</strong>對個人原因退貨或狀態瑕疵但仍協商處理之個案，我們可扣除合理費用後再退餘額。</li>\n</ol>\n\n<h2>4. 退款方式</h2>\n<ul>\n<li>原則退回<strong>原支付途徑</strong>（信用卡／支付平台／其他當次付款渠道）。</li>\n<li>若原途徑無法退回或已失效，我們可在通知你後改以其他合理方式處理（例如商店餘額、優惠券折讓或雙方同意之轉帳安排）。</li>\n<li>我們<strong>不保證</strong>以現金或非原途徑即時退款；具體以可執行之支付渠道規則為準。</li>\n</ul>\n\n<h2>5. 處理與到帳時間</h2>\n<ul>\n<li><strong>起算點：</strong>以我們完成驗貨（如適用）並在系統確認「同意退款」之日起算，而非你提交申請或寄出商品之日。</li>\n<li><strong>我方處理：</strong>確認後一般於 <strong>3–15 個工作天</strong>內提交退款指令（遇對帳、風控、節假日或支付機構審核可能延長）。</li>\n<li><strong>到帳：</strong>支付機構／銀行入帳通常另需數個工作天，實際以對方為準；我們無法控制第三方到帳速度。</li>\n<li>同一訂單多次售後、爭議未決或需補證時，我們可暫停退款直至事項澄清。</li>\n</ul>\n\n<h2>6. 取消訂單與出貨後</h2>\n<ul>\n<li><strong>未出貨：</strong>可申請取消；是否成功視倉庫作業進度。已開始揀貨／交運者，可能無法取消，改按退貨流程。</li>\n<li><strong>已出貨：</strong>不支持僅以「不想要」為由直接線上全額退款；須按《退貨政策》退回並驗貨。</li>\n<li>你已申請支付機構爭議／拒付時，我們可中止雙軌處理，優先以爭議結果及證據為準，並保留提供物流與溝通紀錄之權利。</li>\n</ul>\n\n<h2>7. 部分退款與換貨差價</h2>\n<p>多件訂單可只退符合條件之部分。換貨涉及差價時，多退少補；少補未完成前，我們可暫不發出替換商品。部分退款之運費與優惠重算依第 3 節。</p>\n\n<h2>8. 發票與記錄</h2>\n<p>退款完成後，交易記錄、積分與優惠狀態以系統為準。如需調整發票／收據記載，請在退款完成後聯絡客服，我們於合理範圍協助。</p>\n\n<h2>9. 酌情權與防濫用</h2>\n<p>在適用法律允許範圍內，SisterMart 可就爭議個案作出合理商業判斷（包括部分退款、延期、折讓替代現金、或拒絕）。對異常高頻退貨、拒付或虛假陳述，我們可限制購買／售後權限，並保留追討已退款項及相關損失之權利。</p>\n\n<h2>10. 聯絡與更新</h2>\n<p>電郵 <strong>service@sistermart.vip</strong>；WhatsApp <strong>+852 5598 3063</strong>（10:00–19:00，香港時間）。政策更新以本頁為準；已確認退款之案件不因政策更新而重新計算，另有約定或法律規定除外。</p>\n'
FROM articles a WHERE a.code='refund'
ON DUPLICATE KEY UPDATE title=VALUES(title), body=VALUES(body);

INSERT INTO article_i18n (article_id, locale, title, body)
SELECT a.id, 'en', 'Refund Policy', '<p><strong>Effective date:</strong> 7 November 2026<br>\n<strong>Last updated:</strong> 7 November 2026</p>\n<p>This Refund Policy explains when and how SisterMart issues refunds, together with the Return Policy, Shipping Policy and User Agreement. A refund is not automatic: it must meet this Policy and the Return Policy and pass our review/inspection. To protect lawful merchant interests and prevent abuse, we may verify the transaction, adjust the refund breakdown, pause or stage processing, and refuse or partially refund where reasonable (except where mandatory law requires otherwise).</p>\n\n<h2>1. When we may refund</h2>\n<ul>\n<li>After a return under the Return Policy and a <strong>passed</strong> inbound inspection</li>\n<li>After successful payment, where we fail to ship for a prolonged period due to our reasons and you choose to cancel a cancellable order we confirm</li>\n<li>Verified duplicate charges, pricing system errors, clearly overcharged shipping, or other amount errors attributable to us</li>\n<li>Wrong/missing items where both sides agree to refund instead of reship/exchange</li>\n<li>Other cases we agree to refund in writing</li>\n</ul>\n\n<h2>2. No refund or partial refund only</h2>\n<ul>\n<li>Requests that fail the Return Policy or inspection</li>\n<li>Used promotional benefits, non-reversible third-party fees, or depreciation/missing-parts portions</li>\n<li>Extra logistics costs from wrong address, refusal or unclaimed parcels (may be deducted)</li>\n<li>Gifts, packing consumables or costs already incurred and non-returnable (case by case)</li>\n<li>Suspected fraud, item swapping, chargeback abuse or after-sales abuse</li>\n</ul>\n\n<h2>3. Refund composition</h2>\n<ol>\n<li><strong>Item price:</strong> generally the amount actually paid for that item (after allocating discounts).</li>\n<li><strong>Order promos / thresholds / coupons:</strong> if remaining items no longer meet a campaign threshold after refund, we may claw back the related discount (deduct from refund or require a top-up).</li>\n<li><strong>Points:</strong> points used at checkout may be restored by rule; points earned from the order may be clawed back. Points-mall orders may have stricter refund limits.</li>\n<li><strong>Shipping:</strong>\n  <ul>\n    <li>Quality issues / wrong items: original outbound shipping and approved return shipping may be refunded or reimbursed within reason</li>\n    <li>Non-quality returns: original outbound shipping is usually non-refundable; return/reship shipping is yours</li>\n    <li>Partial returns that break free-shipping eligibility: we may deduct the shipping then due</li>\n  </ul>\n</li>\n<li><strong>Handling / inspection / restocking:</strong> for change-of-mind or imperfect-condition cases still handled by agreement, we may deduct reasonable fees before refunding the balance.</li>\n</ol>\n\n<h2>4. Refund method</h2>\n<ul>\n<li>Refunds generally go to the <strong>original payment method</strong>.</li>\n<li>If that channel cannot receive funds or has expired, we may notify you and use another reasonable method (store credit, coupon goodwill, or an agreed transfer).</li>\n<li>We do <strong>not guarantee</strong> cash or instant non-original-path refunds; provider rules apply.</li>\n</ul>\n\n<h2>5. Timing</h2>\n<ul>\n<li><strong>Start date:</strong> from the day we complete inspection (if any) and confirm “refund approved” in our system—not from your request or ship-back date.</li>\n<li><strong>Our processing:</strong> after confirmation we usually submit the refund instruction within <strong>3–15 business days</strong> (reconciliation, risk checks, holidays or provider review may extend this).</li>\n<li><strong>Arrival:</strong> banks/payment providers often need additional business days; we cannot control their speed.</li>\n<li>Multiple after-sales on one order, open disputes or missing evidence may pause the refund until clarified.</li>\n</ul>\n\n<h2>6. Cancellation vs shipped orders</h2>\n<ul>\n<li><strong>Not yet shipped:</strong> you may request cancellation; success depends on warehouse progress. Once picking/handover started, cancellation may fail and the Return Policy applies.</li>\n<li><strong>Already shipped:</strong> “changed my mind” alone does not entitle an instant full online refund; goods must return and pass inspection under the Return Policy.</li>\n<li>If you open a payment dispute/chargeback, we may pause parallel handling and rely on the dispute record, while retaining the right to submit logistics and communication evidence.</li>\n</ul>\n\n<h2>7. Partial refunds and exchange balances</h2>\n<p>Multi-item orders may be refunded only for eligible lines. Exchange price differences are settled (refund or top-up); we may hold the replacement until any top-up is paid. Shipping and promo recalculation follow Section 3.</p>\n\n<h2>8. Records</h2>\n<p>After refund, orders, points and benefits follow system records. For invoice/receipt adjustments, contact support after the refund completes; we will help within reason.</p>\n\n<h2>9. Discretion and anti-abuse</h2>\n<p>Where law allows, SisterMart may make a reasonable commercial decision on disputed cases (partial refund, delay, goodwill instead of cash, or refusal). For abnormal return frequency, chargebacks or false statements, we may limit purchase/after-sales access and recover refunded sums and related losses.</p>\n\n<h2>10. Contact and updates</h2>\n<p>Email <strong>service@sistermart.vip</strong>; WhatsApp <strong>+852 5598 3063</strong> (10:00–19:00, Hong Kong time). Updates appear on this page. Confirmed refunds are not recalculated solely because the Policy later changes, unless agreed or required by law.</p>\n'
FROM articles a WHERE a.code='refund'
ON DUPLICATE KEY UPDATE title=VALUES(title), body=VALUES(body);

